import{_ as a,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"03｜分而治之：Sub-Agents 的核心概念与应用价值","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么要有Sub-Agents？","slug":"为什么要有sub-agents","link":"#为什么要有sub-agents","children":[]},{"level":2,"title":"什么是子代理？","slug":"什么是子代理","link":"#什么是子代理","children":[]},{"level":2,"title":"子代理的核心价值","slug":"子代理的核心价值","link":"#子代理的核心价值","children":[]},{"level":2,"title":"内置子代理：开箱即用的“好员工”","slug":"内置子代理-开箱即用的-好员工","link":"#内置子代理-开箱即用的-好员工","children":[{"level":3,"title":"Explore 子代理","slug":"explore-子代理","link":"#explore-子代理","children":[]},{"level":3,"title":"Plan 子代理","slug":"plan-子代理","link":"#plan-子代理","children":[]},{"level":3,"title":"General-purpose 子代理","slug":"general-purpose-子代理","link":"#general-purpose-子代理","children":[]}]},{"level":2,"title":"什么时候该用子代理？","slug":"什么时候该用子代理","link":"#什么时候该用子代理","children":[{"level":3,"title":"一条关键约束：子代理不能生成子代理","slug":"一条关键约束-子代理不能生成子代理","link":"#一条关键约束-子代理不能生成子代理","children":[]}]},{"level":2,"title":"子代理配置文件详解","slug":"子代理配置文件详解","link":"#子代理配置文件详解","children":[]},{"level":2,"title":"子代理的存放位置与优先级","slug":"子代理的存放位置与优先级","link":"#子代理的存放位置与优先级","children":[]},{"level":2,"title":"创建子代理的三种方式","slug":"创建子代理的三种方式","link":"#创建子代理的三种方式","children":[]},{"level":2,"title":"子代理的运行模式","slug":"子代理的运行模式","link":"#子代理的运行模式","children":[]},{"level":2,"title":"本讲小结","slug":"本讲小结","link":"#本讲小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]},{"level":2,"title":"下一讲预告","slug":"下一讲预告","link":"#下一讲预告","children":[]}],"relativePath":"ClaudeCode工程化实战/03｜分而治之：Sub-Agents的核心概念与应用价值.md","filePath":"ClaudeCode工程化实战/03｜分而治之：Sub-Agents的核心概念与应用价值.md","lastUpdated":1779815462000}'),l={name:"ClaudeCode工程化实战/03｜分而治之：Sub-Agents的核心概念与应用价值.md"};function t(i,s,o,c,r,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_03-分而治之-sub-agents-的核心概念与应用价值" tabindex="-1">03｜分而治之：Sub-Agents 的核心概念与应用价值 <a class="header-anchor" href="#_03-分而治之-sub-agents-的核心概念与应用价值" aria-label="Permalink to &quot;03｜分而治之：Sub-Agents 的核心概念与应用价值&quot;">​</a></h1><p>你好，我是黄佳。</p><p>欢迎来到 Claude Code 工程化实战的第三讲。从这一讲开始，我们将进入本课程的第一个核心内容—— <strong>子代理（Sub-Agents）</strong>。</p><h2 id="为什么要有sub-agents" tabindex="-1">为什么要有Sub-Agents？ <a class="header-anchor" href="#为什么要有sub-agents" aria-label="Permalink to &quot;为什么要有Sub-Agents？&quot;">​</a></h2><p>我们先从一个常见场景开启今天的内容。</p><p>某天，你让 Claude Code 帮你跑一个测试套件，结果输出了 500 行日志；然后你想让它分析一下代码结构，又输出了 200 行；接着你想让它改一个 bug……这时候，你的对话上下文已经被各种“中间过程”塞满了，真正重要的信息被淹没在茫茫的输出海洋里。</p><p>其实，究其根本。如果你觉得 Claude Code 越用越“健忘”，并不是模型退化了，而是你的对话上下文，已经被一次次中间过程 <strong>污染</strong> 了。</p><p>这正是子代理要解决的核心问题。</p><p>你或许还会追问——别卖关子，佳哥。到底子代理解决了什么核心问题？更明确的答案是：如何把“高噪声的执行过程”隔离出去，只让真正有价值的结论，留在主对话中。</p><p>因为只有子代理，才在系统层面 <strong>天然拥有一个独立的上下文窗口。</strong> 不是因为它“聪明”，不是因为它“更强”， 而是因为它是 Claude Code 里唯一一个，结构上允许“执行完即丢弃”的东西。</p><p>我们再进一步把问题说明清楚：到底什么是“上下文污染”？</p><p>在前面的现象里，上下文里充斥着这些内容。</p><ul><li><p>跑测试 → 500 行日志。</p></li><li><p>搜索代码 → 200 行 grep。</p></li><li><p>分析错误 → 一堆中间推理过程……</p></li></ul><p>这些信息有一个共同特征：它们 <strong>对“当下执行”是必要的，但对“后续决策”是噪声</strong>。</p><p>而 Claude Code 的主对话上下文是线性追加的，不会自动过期，默认“都当成重要记忆”。所以问题不是 Claude 突然不聪明了 ，而是它把临时执行数据，当成了长期决策记忆。 这在工程上，本来就一定会“炸”。</p><p>那为什么偏偏是子代理能解决这个问题呢？</p><p>重点来了 —— <strong>不是AI Agent这个概念能解决问题，而是 Sub-Agent 这种“运行模型”在起作用。</strong> 子代理，通过上下文隔离，让专业的Agent做专业的事儿，不是为了让 Claude 做得更多， 而是为了让 Claude <strong>记得更少，但记得对</strong>。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/83faca2955fec9918cde91336954436b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/83faca2955fec9918cde91336954436b.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/bff23d0b23e5cf0517ec0f42d3c97140.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/bff23d0b23e5cf0517ec0f42d3c97140.jpg" alt=""></a></p><p>PS：OpenClaw链接： <a href="https://github.com/openclaw/openclaw" target="_blank" rel="noreferrer">https://github.com/openclaw/openclaw</a></p><p>下面，我们会深入理解子代理的核心概念，明白它为什么是 Claude Code 工程化使用中最重要的能力之一。理解了这些概念，后面几讲的实战项目你才能得心应手。</p><h2 id="什么是子代理" tabindex="-1">什么是子代理？ <a class="header-anchor" href="#什么是子代理" aria-label="Permalink to &quot;什么是子代理？&quot;">​</a></h2><p>我们可以用一句话定义它。子代理相当于一个“专职小助手”，带着自己的规则、工具权限、上下文窗口，去完成某一类任务，然后把“结果摘要”带回来。你可以把它理解成： <strong>把一个大脑拆成多个岗位角色</strong>，每个岗位只做一件事，并且有明确的权限边界。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/cb46b69c3fe2d551635019829d97b777.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/cb46b69c3fe2d551635019829d97b777.png" alt="图片"></a></p><p>图中目录下设置了 3 个专门的子代理，用于处理循环经济知识图谱项目。这三个代理形成了一个完整的工作流：组织 PDF → 提取知识图谱 → 分析结果。</p><p>不过这里还有另外一个问题，就是有Sub-Agent，那肯定要先有主Agent，Claude Code的主Agent在何处？其实，主Agent就是你当前操作的主对话。而主对话 vs 子代理，就是老板和员工的关系。</p><p>一家公司的老板（主对话）需要完成一个复杂的项目，有两种工作方式。</p><ul><li><p><strong>方式一：事必躬亲：</strong> 亲自去调研市场（输出 200 行分析）、亲自写代码（输出 500 行日志）、亲自测试（又是 300 行）、亲自写文档……最后脑子里塞满了各种细节，已经记不清最初的目标是什么了。</p></li><li><p><strong>方式二：专人专岗</strong>：安排一个市场专员去调研，只需要他给你一份 1 页的报告；安排一个测试工程师去跑测试，只需要他告诉你结果是“通过”还是“有 3 个失败”；安排一个技术文档专员去写文档……每个人带着明确的任务出去，完成后只把 <strong>结论</strong> 带回来。</p></li></ul><p>子代理就是后一种方式。它让主对话保持清洁，不被过程噪声污染。</p><h2 id="子代理的核心价值" tabindex="-1">子代理的核心价值 <a class="header-anchor" href="#子代理的核心价值" aria-label="Permalink to &quot;子代理的核心价值&quot;">​</a></h2><p>子代理的工程价值，本质上就是三件事： <strong>隔离、约束、复用</strong>，下面我们分别说说。</p><p><strong>隔离，解决的是上下文污染问题</strong>——大量对当前执行有用、但对后续决策毫无价值的日志、搜索结果和中间推理，不应该进入主对话的长期记忆；子代理天然拥有独立上下文，执行完即丢弃，只把结论带回来，让 Claude 记得更少、但记得对。</p><p>这是子代理最重要的价值，请看下面的示例。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主对话的上下文：</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 用户：帮我分析一下这个 bug              │</span></span>
<span class="line"><span>│ Claude：好的，让我看看...               │</span></span>
<span class="line"><span>│ [子代理去执行，产生 500 行日志]         │</span></span>
<span class="line"><span>│ [子代理返回：发现 3 个相关文件]         │</span></span>
<span class="line"><span>│ Claude：我发现问题在这三个文件...       │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>子代理的上下文（独立的，执行完就释放）：</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 任务：查找 bug 相关文件                 │</span></span>
<span class="line"><span>│ [搜索输出 500 行日志]                   │</span></span>
<span class="line"><span>│ [分析过程...]                           │</span></span>
<span class="line"><span>│ 结论：3 个相关文件                      │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre></div><p>主对话只看到子代理所返回的 <strong>结论</strong>，不需要承载 500 行的搜索过程。这意味着你的对话不会因为一次大搜索就把 token 配额用光，重要的讨论内容不会被中间输出淹没，Claude 在后续对话中能更好地“记住”关键信息。</p><p><strong>约束，解决的是行为不可控问题</strong>——通过工具权限边界，把“我希望你别这么做”变成“你物理上做不到”，让代码审查只能读、修 bug 才能写，角色职责不再依赖提示词自觉。</p><p>子代理可以有精确的工具权限控制。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 只读型子代理（代码审查）</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span># 它只能看，不能改任何东西</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 开发型子代理（bug 修复）</span></span>
<span class="line"><span>tools: Read, Write, Edit, Bash</span></span>
<span class="line"><span># 它可以读写文件和执行命令</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 研究型子代理（技术调研）</span></span>
<span class="line"><span>tools: Read, WebFetch, WebSearch</span></span>
<span class="line"><span># 它可以读本地文件和搜索网络</span></span></code></pre></div><p>为什么这很重要？</p><p>比如你让 Claude 帮你审查代码，你只希望它看，不希望它动手改。如果没有权限边界，Claude 可能在审查过程中顺手帮你“修”了一些它认为有问题的代码——这不是你想要的行为。有了子代理，你就可以创建一个 <code>code-reviewer</code> 角色，明确规定它只有 <code>Read, Grep, Glob</code> 权限。这样它再怎么想“插手”，也改不了任何东西。</p><p><strong>复用，解决的是经验无法沉淀的问题</strong>——当子代理被定义成文件、放进版本控制后，好的使用方式就从一次性对话，变成了可共享、可迭代的工程资产。</p><p>子代理的配置保存在文件中，有这样几个好处。</p><ul><li><p><strong>版本控制</strong>：放进 git，团队共享。</p></li><li><p><strong>跨项目复用</strong>：好用的配置可以复制到其他项目。</p></li><li><p><strong>渐进优化</strong>：根据实际使用情况不断调整 prompt，持续优化改善。</p></li></ul><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.claude/agents/</span></span>
<span class="line"><span>├── test-runner.md      # 测试运行专员</span></span>
<span class="line"><span>├── code-reviewer.md    # 代码审查专员</span></span>
<span class="line"><span>├── log-analyzer.md     # 日志分析专员</span></span>
<span class="line"><span>└── bug-fixer.md        # Bug 修复专员</span></span></code></pre></div><p>这些配置文件就像公司里的“岗位说明书”，每个岗位职责清晰、权限明确。</p><p>这三点，分别对应着三个经典的软件工程命题： <strong>内存管理、安全边界、组织效率</strong>。这三点合在一起，标志着 Claude Code 的使用方式，从“对话技巧”，正式跨入“工程系统”。</p><h2 id="内置子代理-开箱即用的-好员工" tabindex="-1">内置子代理：开箱即用的“好员工” <a class="header-anchor" href="#内置子代理-开箱即用的-好员工" aria-label="Permalink to &quot;内置子代理：开箱即用的“好员工”&quot;">​</a></h2><p>你可能已经在使用子代理，只是没意识到而已。Claude Code 内置了一系列子代理（以后也许会有更多），当你问Claude——“给我解释解释这个Github代码库”时，在不知不觉间，Claude Code就会自动调用内置子代理。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/f5376b6df040e7ab608cc636f35224c5.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/f5376b6df040e7ab608cc636f35224c5.jpg" alt=""></a></p><p>下面简单介绍其中的三个。</p><h3 id="explore-子代理" tabindex="-1">Explore 子代理 <a class="header-anchor" href="#explore-子代理" aria-label="Permalink to &quot;Explore 子代理&quot;">​</a></h3><p><strong>Explore 子代理</strong> 负责“翻项目、找位置”，专注快速只读搜索，把成百上千行 grep 和分析过程吞进去，只告诉你结论在哪里。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Explore（探索者）                                       │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  特点：快速、只读                                        │</span></span>
<span class="line"><span>│  用途：搜索和分析代码库                                  │</span></span>
<span class="line"><span>│  模式：quick / medium / very thorough 三档              │</span></span>
<span class="line"><span>│  工具：Read, Grep, Glob（不能写）                        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>当你问 Claude“这个项目的认证逻辑在哪里”时，它会自动派出 Explore 子代理去搜索，而不是在主对话中一行行地执行 grep 命令。</p><h3 id="plan-子代理" tabindex="-1">Plan 子代理 <a class="header-anchor" href="#plan-子代理" aria-label="Permalink to &quot;Plan 子代理&quot;">​</a></h3><p><strong>Plan 子代理</strong> 负责“动手前先想清楚”，在真正修改代码之前，收集上下文、梳理依赖、生成实施路径，避免一上来就盲目修改。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Plan（规划者）                                          │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  特点：规划模式专用                                      │</span></span>
<span class="line"><span>│  用途：在制定实施计划前收集项目上下文                     │</span></span>
<span class="line"><span>│  限制：子代理不能再生成子代理（防止无限嵌套）             │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>当你让 Claude 进入规划模式时，它会用 Plan 子代理来收集信息，设计实施方案。</p><h3 id="general-purpose-子代理" tabindex="-1">General-purpose 子代理 <a class="header-anchor" href="#general-purpose-子代理" aria-label="Permalink to &quot;General-purpose 子代理&quot;">​</a></h3><p><strong>General-purpose 子代理</strong> 则是“能探索、能修改、能推进”的全能型员工，适合需要多步骤协作的复杂任务。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  General-purpose（通用型）                               │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│  特点：全能型，处理复杂多步骤任务                         │</span></span>
<span class="line"><span>│  用途：同时需要探索和修改的任务                          │</span></span>
<span class="line"><span>│  工具：完整工具集                                        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>当任务比较复杂，需要多种能力配合时，就可以使用这个通用型子代理。这些子代理的共同点只有一个： <strong>把高噪声过程留在子代理里，让主对话只保留决策信息。</strong></p><h2 id="什么时候该用子代理" tabindex="-1">什么时候该用子代理？ <a class="header-anchor" href="#什么时候该用子代理" aria-label="Permalink to &quot;什么时候该用子代理？&quot;">​</a></h2><p>需要提醒你的事，并不是所有任务都值得动用子代理。子代理的价值，不在于“能不能用”，而在于“该不该用”。一个最直观的判断标准是： <strong>主对话到底需不需要承载执行过程本身</strong>。</p><p><strong>第一类</strong> 非常适合用子代理的，是 <strong>高噪声输出的任务</strong>。这类任务的共同特点是：执行过程中会产生大量中间信息，但主对话真正关心的，往往只有一个结论。</p><p>例如跑一次测试会输出几百行日志，但你只想知道通过还是失败；扫描日志和错误栈时，真正有价值的可能只是一两条关键错误；在整个代码库里做搜索，最终只需要知道相关文件在哪里；生成一份长报告，主对话只需要摘要。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/75dcb95964d90e48d6a80fe25edc0f81.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/75dcb95964d90e48d6a80fe25edc0f81.png" alt=""></a></p><p>这些场景中，执行过程本身就是噪声，用子代理把过程隔离起来，只把结论带回来，是最自然、也最干净的做法。</p><p><strong>第二类</strong> 适合用子代理的，是 <strong>角色边界必须非常明确的任务</strong>。有些事情，你只希望 Claude “看”，而不希望它“动手”；有些操作，只能在特定目录、特定范围内发生；还有一些敏感操作，本身就需要和其他任务隔离开来。</p><p>如果没有子代理，这些约束只能靠提示词和使用者的心理预期维持。而一旦通过子代理定义工具权限，边界就从不稳定的“希望如此”，变成了明确的“系统级约束”。没有写权限，就无法修改文件；没有执行权限，就无法运行命令。正因为边界被落实为能力边界，而不是行为约定，子代理才成为解决安全性和可控性问题的可靠手段。</p><p><strong>第三类</strong> 适合用子代理的，是 <strong>可以并行展开的研究型任务</strong>。当你需要同时调研认证逻辑、数据库设计和 API 接口，或者对比几种技术方案、从多个视角分析同一个问题时，这些探索之间往往是相互独立的。与其在主对话里来回切换，不如让多个子代理各自去完成自己的探索，再把结果汇总回来。子代理在这里的价值，不只是隔离上下文，更是天然的并行加速器。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/4300cf4660d830b21b96b7f6bdb960e8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/4300cf4660d830b21b96b7f6bdb960e8.png" alt=""></a></p><p><strong>第四类</strong> 适合用子代理的，是 <strong>可以拆成清晰阶段的流水线式任务</strong>。比如先定位代码位置，再做代码审查，然后进行修改，最后跑测试验证。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Explore（找位置）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Reviewer（指出问题）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Fixer（修复）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Test-runner（验证）</span></span></code></pre></div><p>这类任务的关键在于每一个阶段的目标、权限和输出都是明确的。用子代理把每一段责任固定下来，不但让流程更清晰，也让每一步的上下文更加干净。这不是为了复杂化流程，而是为了避免不同阶段的信息互相污染。</p><p>当然，也有一些情况并不适合使用子代理。如果任务需要频繁来回确认需求、不断调整方向，那子代理这种“派出去干活再回来汇报”的模式反而会拖慢节奏；如果任务的各个阶段高度耦合，每一步都强依赖上一阶段的详细过程，那强行隔离上下文只会增加认知负担；还有非常简单的小任务，启动子代理本身就有开销，直接在主对话中完成，反而更高效。</p><h3 id="一条关键约束-子代理不能生成子代理" tabindex="-1">一条关键约束：子代理不能生成子代理 <a class="header-anchor" href="#一条关键约束-子代理不能生成子代理" aria-label="Permalink to &quot;一条关键约束：子代理不能生成子代理&quot;">​</a></h3><p>请注意一条很容易被忽略但影响深远的架构限制—— <strong>子代理不能再嵌套调用子代理</strong>。也就是说，你的 code-reviewer 子代理不能在执行过程中再派出一个 security-scanner 子代理。</p><p>这意味着什么？</p><ol><li><p><strong>所有编排必须由主对话完成</strong>：如果你需要“先审查再修复”，必须由主对话依次调用两个子代理，而不是让第一个子代理去调用第二个</p></li><li><p><strong>流水线的“调度中心”只有一个</strong>：就是主对话本身（后续第 6 讲会深入讨论这一点）</p></li><li><p><strong>如果需要在子代理内复用知识</strong>：用 <code>skills</code> 字段预加载（而非再嵌套一个子代理），后面配置详解中我们会讲到。</p></li></ol><p>理解这条约束，你就不会在设计复杂工作流时走弯路。</p><h2 id="子代理配置文件详解" tabindex="-1">子代理配置文件详解 <a class="header-anchor" href="#子代理配置文件详解" aria-label="Permalink to &quot;子代理配置文件详解&quot;">​</a></h2><p>好，讲到这里，相信你已经对为什么我们需要子代理有了清晰的理解。下面直接进入实操环节，看看如何创建子代理的配置文件。</p><p>首先我们看看子代理的配置文件格式（可以参考我的Github Repo中的03-SubAgents各个项目中的子代理示例）。</p><p>子代理使用 <strong>Markdown + YAML frontmatter</strong> 格式：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: code-reviewer</span></span>
<span class="line"><span>description: Review code for security issues and best practices. Use after code changes.</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span>model: sonnet</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你是一个代码审查专家。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>当被调用时：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 首先理解代码变更的范围</span></span>
<span class="line"><span>2. 检查安全问题</span></span>
<span class="line"><span>3. 检查代码规范</span></span>
<span class="line"><span>4. 提供改进建议</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出格式：</span></span>
<span class="line"><span>## 审查结果</span></span>
<span class="line"><span>- 安全问题：[列表]</span></span>
<span class="line"><span>- 规范问题：[列表]</span></span>
<span class="line"><span>- 建议：[列表]</span></span></code></pre></div><p>frontmatter 部分（ <code>---</code> 之间）定义子代理的元数据和配置，下方的 Markdown 正文就是子代理的系统提示词（system prompt）。子代理只会收到这段系统提示词和基本环境信息（如工作目录）， <strong>不会</strong> 继承主对话的完整系统提示词。</p><p>上述文件中出现的以及未出现的 frontmatter 字段详解如下。其中 <code>name</code> 和 <code>description</code> 是必填字段，其余均为可选：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/5425ae5d7b516fa10f1bd76ae4c09acf.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/5425ae5d7b516fa10f1bd76ae4c09acf.jpg" alt=""></a></p><p>下面对几个关键字段做重点说明。</p><p><strong>description 的设计艺术</strong></p><p><code>description</code> 字段决定了 Claude <strong>何时自动调用</strong> 你的子代理——这是配置中最重要的设计决策。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 写的太模糊，Claude 不知道什么时候该用它</span></span>
<span class="line"><span>description: A code reviewer</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 好的 description：说明做什么 + 什么时候用</span></span>
<span class="line"><span>description: Review code changes for quality, security vulnerabilities, and best practices. Use proactively after code is modified or when user asks for code review.</span></span></code></pre></div><p>优点：说明了 <strong>做什么</strong>（审查代码质量、安全、规范）和 <strong>什么时候用</strong>（代码修改后，或用户请求时）。“Proactively” 这个关键词会鼓励 Claude 在合适的时机主动委派任务。</p><p><strong>tools vs disallowedTools：白名单与黑名单</strong></p><p>控制子代理能使用哪些工具有两种方式：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 方式一：白名单 (tools) — &quot;只能用这些&quot;</span></span>
<span class="line"><span># 适合：需要严格限制的场景（如只读审查）</span></span>
<span class="line"><span>tools: Read, Grep, Glob</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 方式二：黑名单 (disallowedTools) — “继承所有，但排除这些”</span></span>
<span class="line"><span># 适合：需要大部分工具但排除少数危险工具的场景</span></span>
<span class="line"><span>disallowedTools: Write, Edit</span></span></code></pre></div><p>两者的选择取决于你想要的表达方式：如果子代理只需要少数几个工具，用白名单更清晰；如果子代理需要大部分工具但排除个别，用黑名单更简洁。 <strong>不要同时使用两者</strong>——选一种即可。</p><p>工具权限应遵循最小权限原则——只开放必要的工具，能用 Read 完成的任务，就不要给 Edit。以下是根据用途划分的典型工具组合：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>只读型（审计/检查）         研究型（信息收集）         开发型（读写改）</span></span>
<span class="line"><span>├── Read                    ├── Read                   ├── Read</span></span>
<span class="line"><span>├── Grep                    ├── Grep                   ├── Write</span></span>
<span class="line"><span>└── Glob                    ├── Glob                   ├── Edit</span></span>
<span class="line"><span>                            ├── WebFetch               ├── Bash</span></span>
<span class="line"><span>                            └── WebSearch              ├── Glob</span></span>
<span class="line"><span>                                                       └── Grep</span></span></code></pre></div><p><strong>model：模型选择与默认值</strong></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/71cd4c92058b3c50239712630fd338d6.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/71cd4c92058b3c50239712630fd338d6.jpg" alt=""></a></p><p><strong>permissionMode：权限模式</strong></p><p><code>permissionMode</code> 控制子代理在执行过程中遇到需要权限的操作时如何处理。子代理会继承主对话的权限上下文，但可以通过此字段覆盖行为：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/9c630b6f0065eb1d725e8cd6060016a6.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/9c630b6f0065eb1d725e8cd6060016a6.jpg" alt=""></a></p><p>举个例子，如果你希望子代理能跑 <code>git diff</code> 但绝不能修改文件，可以这样配置：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: code-reviewer</span></span>
<span class="line"><span>tools: Read, Grep, Glob, Bash</span></span>
<span class="line"><span>permissionMode: plan          # 强制只读模式，即使有 Bash 也无法写入</span></span>
<span class="line"><span>---</span></span></code></pre></div><p>这比单纯依赖 prompt 约束更可靠—— <code>permissionMode: plan</code> 是 <strong>系统级</strong> 的只读保障。</p><p><strong>skills：为子代理预加载知识</strong></p><p><code>skills</code> 字段允许你在子代理启动时，把指定 Skill 的完整内容注入到子代理的上下文中。这意味着子代理不需要在执行过程中发现和加载Skill——知识已经在它的脑子里了。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: impact-analyzer</span></span>
<span class="line"><span>description: Analyze impact scope of code changes on the full call chain.</span></span>
<span class="line"><span>tools: Read, Grep, Glob, Bash</span></span>
<span class="line"><span>skills:</span></span>
<span class="line"><span>  - chain-knowledge        # 链路拓扑和 SLA 约束</span></span>
<span class="line"><span>  - recent-incidents       # 近期事故记录</span></span>
<span class="line"><span>---</span></span></code></pre></div><p>子代理 <strong>不会</strong> 自动继承主对话中可用的 Skill。如果你希望子代理拥有某个 Skill 的知识，必须在这里显式列出。这个机制在后续讲解中会结合实战案例深入展开。</p><p><strong>hooks：子代理专属的生命周期 Hook</strong></p><p>子代理可以在自己的 frontmatter 中定义 Hook——这些 Hook <strong>只在该子代理运行期间生效</strong>，子代理结束后自动清理。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: db-reader</span></span>
<span class="line"><span>description: Execute read-only database queries.</span></span>
<span class="line"><span>tools: Bash</span></span>
<span class="line"><span>hooks:</span></span>
<span class="line"><span>  PreToolUse:</span></span>
<span class="line"><span>    - matcher: &quot;Bash&quot;</span></span>
<span class="line"><span>      hooks:</span></span>
<span class="line"><span>        - type: command</span></span>
<span class="line"><span>          command: &quot;./scripts/validate-readonly-query.sh&quot;</span></span>
<span class="line"><span>---</span></span></code></pre></div><p>上面的例子中， <code>db-reader</code> 虽然拥有 Bash 工具，但每次执行 Bash 命令前都会被 Hook 拦截验证——只有 SELECT 查询能通过，INSERT/UPDATE/DELETE 等写操作会被阻止。这比不给 Bash 工具更灵活（允许读操作），又比无约束的 Bash 更安全。</p><p>Hook 的详细机制我们会在后续 Hook 专题课程中展开。这里先建立概念： <strong>子代理不仅可以控制有哪些工具，还可以控制工具能做什么操作</strong>。</p><h2 id="子代理的存放位置与优先级" tabindex="-1">子代理的存放位置与优先级 <a class="header-anchor" href="#子代理的存放位置与优先级" aria-label="Permalink to &quot;子代理的存放位置与优先级&quot;">​</a></h2><p>子代理可以被设置为不同的作用域。当多个作用域存在同名子代理时，高优先级的会覆盖低优先级的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/a72ae303f03a261b1c6e8yy4d0ae2132.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/a72ae303f03a261b1c6e8yy4d0ae2132.jpg" alt=""></a></p><p>子代理可以被设置为项目级或用户级， <strong>项目级</strong>（仅当前项目可用）存放位置如下所示，适合项目特有的角色，比如针对特定框架的测试运行器</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-project/</span></span>
<span class="line"><span>└── .claude/</span></span>
<span class="line"><span>    └── agents/</span></span>
<span class="line"><span>        ├── test-runner.md</span></span>
<span class="line"><span>        └── code-reviewer.md</span></span></code></pre></div><p><strong>用户级</strong>（所有项目可用）子代理适合通用角色，比如日志分析器、通用代码审查器。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.claude/</span></span>
<span class="line"><span>└── agents/</span></span>
<span class="line"><span>    ├── general-reviewer.md</span></span>
<span class="line"><span>    └── log-analyzer.md</span></span></code></pre></div><h2 id="创建子代理的三种方式" tabindex="-1">创建子代理的三种方式 <a class="header-anchor" href="#创建子代理的三种方式" aria-label="Permalink to &quot;创建子代理的三种方式&quot;">​</a></h2><p>弄清了子代理配置文件的格式和位置，就可以创建子代理了。有三种创建方式，我们分别来看看。</p><p><strong>方式一</strong>： <strong>交互式创建</strong>（推荐新手使用）。在 Claude Code 中输入 <code>/agents</code>，按照向导操作：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>步骤 1：输入 /agents</span></span>
<span class="line"><span>步骤 2：选择 &quot;Create new agent&quot;</span></span>
<span class="line"><span>步骤 3：选择存放位置（User-level 或 Project-level）</span></span>
<span class="line"><span>步骤 4：选择 &quot;Generate with Claude&quot; 并描述功能</span></span>
<span class="line"><span>步骤 5：选择需要的工具</span></span>
<span class="line"><span>步骤 6：选择模型</span></span>
<span class="line"><span>步骤 7：保存</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/51f77f6bcc00d9fc27d0994914c99401.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/51f77f6bcc00d9fc27d0994914c99401.png" alt="图片"></a></p><p>这种方式简单直观，Claude 会帮你生成初始的 prompt。</p><p><strong>方式二</strong>： <strong>手写配置文件</strong>，直接创建 <code>.claude/agents/your-agent.md</code> 文件。其优势是更精细的控制，方便版本管理，可以从其他项目复制。</p><p><strong>方式三：CLI 参数临时创建</strong>，通过 <code>--agents</code> 参数，可以在启动 Claude Code 时传入 JSON 格式的子代理定义。这种方式创建的子代理仅在当前会话中存在，不会保存到磁盘。这种方式特别适合CI/CD 自动化时在流水线中临时创建任务专用的子代理。</p><h2 id="子代理的运行模式" tabindex="-1">子代理的运行模式 <a class="header-anchor" href="#子代理的运行模式" aria-label="Permalink to &quot;子代理的运行模式&quot;">​</a></h2><p>子代理不只是“派出去，等回来”这么简单。了解它的运行模式，能让你更高效地使用。</p><p>子代理可以在前台或后台运行。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/5d5c1d1f462db70663df2688051236fc.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E5%B7%A5%E7%A8%8B%E5%8C%96%E5%AE%9E%E6%88%98/images/943368/5d5c1d1f462db70663df2688051236fc.jpg" alt=""></a></p><p>Claude 会根据任务自动选择前台或后台。你也可以手动控制。</p><ul><li><p>对 Claude 说 “run this in the background”</p></li><li><p>正在运行的前台子代理可以按 Ctrl+B 切换到后台</p></li></ul><p>启动前，Claude Code 会预先请求子代理可能需要的所有权限——因为后台运行时无法弹出交互式确认。如果后台子代理因权限不足而失败，你可以恢复它到前台重试。</p><p>每个子代理执行完成后，Claude 会自动收到它的 <code>agent ID</code>。如果你需要在之前的子代理基础上 <strong>继续工作</strong>，可以让 Claude 恢复（Resume）它：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用 code-reviewer 子代理审查认证模块</span></span>
<span class="line"><span>[子代理完成]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>继续刚才的审查，再看一下授权逻辑</span></span>
<span class="line"><span>[Claude 恢复之前的子代理，保留完整上下文]</span></span></code></pre></div><p>恢复的子代理会保留所有之前的对话历史——它从上次停下的地方继续，而不是重新开始。这对于需要多轮迭代的长任务非常有用。</p><h2 id="本讲小结" tabindex="-1">本讲小结 <a class="header-anchor" href="#本讲小结" aria-label="Permalink to &quot;本讲小结&quot;">​</a></h2><p>子代理的核心工程化能力归结起来是四件事。</p><p><strong>隔离</strong>，让主对话保持清洁，避免执行噪声污染上下文。</p><p><strong>约束</strong>，通过工具权限把角色边界变成系统规则。</p><p><strong>复用</strong>，把一次好用的经验沉淀为可版本化的配置。</p><p><strong>并行</strong>，让原本串行的复杂任务可以同时推进。</p><p>在配置层面，真正重要的字段也只有几个： <code>name</code> 用来标识角色， <code>description</code> 决定何时被调用（也是最关键的设计点）， <code>tools</code> 划定权限边界， <code>model</code> 则是在性能与成本之间做权衡。</p><p>至于什么时候该用子代理，可以用一句话判断： <strong>当任务存在高噪声输出、需要明确权限边界、可以并行推进或能够拆成清晰阶段时，用子代理；当任务需要频繁来回讨论和即时调整时，就不要用。</strong></p><p>记住上面的几句话，你就理解了子代理的全部精髓。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>如果要设计一个“数据库查询分析器”子代理，你会给它配置哪些工具？为什么？</p></li><li><p>在团队协作中，子代理配置应该放在项目级还是用户级？各有什么优缺点？</p></li><li><p>回顾本讲介绍的 <code>permissionMode</code> 字段。如果你要创建一个“自动化修复”子代理，允许它自主修改文件而不需要每次都弹窗确认，你会选择哪种权限模式？这样做的风险是什么？你会配合哪些其他字段来降低风险？</p></li></ol><h2 id="下一讲预告" tabindex="-1">下一讲预告 <a class="header-anchor" href="#下一讲预告" aria-label="Permalink to &quot;下一讲预告&quot;">​</a></h2><p>下一讲我们将进入实战环节，创建一个 <strong>只读型代码审查子代理</strong>。你将亲手配置一个只能“看”不能“改”的安全审计角色，体验权限边界的工程价值。</p><p>欢迎你在留言区和我交流讨论。如果这一讲对你有启发，别忘了分享给身边更多朋友。</p>`,156)])])}const u=a(l,[["render",t]]);export{h as __pageData,u as default};
